/**
 * Fish Completion Template
 */

import { ShellScriptOptions } from "../types";

/**
 * Generate Fish completion script
 */
export function fishTemplate(options: ShellScriptOptions): string {
  const { binName } = options;

  return `# ${binName} completion script for Fish
# Generated by pontx completion:generate

function __${binName}_completions
  set -l line (commandline -cp)
  set -l tokens (string split ' ' -- $line)
  set -l word_index (count $tokens)

  # If line ends with space, we're completing a new word
  if string match -qr '\\s\$' -- $line
    set word_index (math $word_index)
  else
    set word_index (math $word_index - 1)
  end

  # Call CLI to get completion suggestions
  ${binName} --get-completions "$line" $word_index --format=fish 2>/dev/null
end

# -f: no file completion
# -k: keep order of completions
complete -c ${binName} -f -k -a "(__${binName}_completions)"
`;
}

/**
 * Get Fish installation instructions
 */
export function fishInstallInstructions(binName: string): string {
  return `# Save to Fish completions directory:
${binName} completion generate --shell=fish > ~/.config/fish/completions/${binName}.fish

# The completion will be automatically loaded on next shell session
`;
}
